\subsection{Definitions and mathematical statement}
\paragraph{Shared notation.}$\mathbb N$, $\mathbb Z$, $\mathbb Q$, $\mathbb R$, and $\mathbb C$ denote the natural numbers, integers, rationals, reals, and complex numbers, respectively. All additional parameters and hypotheses are specified in the question.


\paragraph{Statement recorded in the supplied source.}
If a bounded solution of
$$\Delta u+(1-u^2)u=0\quad\text{in }\mathbb R^N$$
satisfies $\partial_{x_N}u>0$, must all level sets of $u$ be hyperplanes when $N\leq8$?
\par\smallskip\textit{Formulation references:} \href{https://huggingface.co/datasets/ulamai/UnsolvedMath}{[S1]}, \href{https://doi.org/10.4171/owr/2012/36}{[S2]}.

\subsection{Short English statement}
If a bounded solution of
$$\Delta u+(1-u^2)u=0\quad\text{in }\mathbb R^N$$
satisfies $\partial_{x_N}u>0$, must all level sets of $u$ be hyperplanes when $N\leq8$?

\subsection{Sources}
\begin{itemize}
\item[S1] ULAM.AI and the UnsolvedMath Contributors, UnsolvedMath: A Curated Collection of Open Mathematics Problems, record 30002144 (OWR-12008-004). Catalogue attribution under CC BY 4.0.
\url{https://huggingface.co/datasets/ulamai/UnsolvedMath}.
\item[S2] Original problem formulation and mathematical context.
\url{https://doi.org/10.4171/owr/2012/36}.
\end{itemize}
\label{end:30002144}

